#!/usr/bin/env python3
# SPDX-License-Identifier: Apache-2.0
"""Generate the original reflected slicing tables; --check never writes."""
from pathlib import Path
import argparse
import hashlib
import json
import struct

ROOT = Path(__file__).resolve().parents[1]
HEADER = ROOT / 'Source/src/crc32_tables.h'
POLYNOMIALS = (0xedb88320, 0x82f63b78)


def bitwise(value, bits, poly):
    for _ in range(bits):
        value = (value >> 1) ^ (poly if value & 1 else 0)
    return value


def tables():
    result = []
    for poly in POLYNOMIALS:
        # This recurrence is exactly the old crc32_tab_init mathematics.
        rows = [[bitwise(i, 8, poly) for i in range(256)]]
        for _ in range(1, 8):
            rows.append([(v >> 8) ^ rows[0][v & 255] for v in rows[-1]])
        # Independent direct polynomial advance, without any table lookup.
        for j, row in enumerate(rows):
            for i, value in enumerate(row):
                assert value == bitwise(i, 8*(j+1), poly)
        result.append(rows)
    for poly, golden in zip(POLYNOMIALS, (0xcbf43926, 0xe3069283)):
        value = 0xffffffff
        for byte in b'123456789':
            value = bitwise(value ^ byte, 8, poly)
        assert value ^ 0xffffffff == golden
    return result


def render(data):
    lines = ['/* SPDX-License-Identifier: Apache-2.0 */',
             '/* Generated by Tools/generate_crc32_tables.py; do not edit.',
             ' * Original CRC32/CRC32C reflected slicing-by-8 values, immutable.',
             ' * No host crypto feature, runtime initialization or writable table. */',
             '#ifndef A64_CRC32_TABLES_H', '#define A64_CRC32_TABLES_H',
             '#include "types.h"',
             'static const u32 a64_crc32_slicing_tables[2][8][256] = {']
    for poly, rows in zip(POLYNOMIALS, data):
        lines.append('    { /* reflected polynomial 0x%08x */' % poly)
        for row in rows:
            lines.append('        {')
            for i in range(0, 256, 8):
                lines.append('            '+','.join('0x%08xu' % v for v in row[i:i+8])+',')
            lines.append('        },')
        lines.append('    },')
    lines += ['};', '_Static_assert(sizeof(a64_crc32_slicing_tables)==16384, "4096 immutable u32 CRC values");', '#endif', '']
    return '\n'.join(lines).encode()


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    data = tables()
    expected = render(data)
    if args.check:
        assert HEADER.read_bytes() == expected, 'generated CRC header drift'
    else:
        assert not HEADER.exists(), 'refuse to overwrite an existing generated header'
        HEADER.write_bytes(expected)
    binary = b''.join(struct.pack('<I', v) for rows in data for row in rows for v in row)
    assert len(binary) == 16384
    print(json.dumps({'read_only_check': args.check, 'values': 4096,
                      'independent_bitwise_each_value': True,
                      'standard_123456789_CRC32_CRC32C': ['cbf43926','e3069283'],
                      'header_sha256': hashlib.sha256(expected).hexdigest(),
                      'little_endian_16KiB_values_sha256': hashlib.sha256(binary).hexdigest(),
                      'native_actions': 0}))


if __name__ == '__main__':
    main()
